#!/usr/bin/env node
// shout — tiny demo CLI (dwarves-kit fixture)
//
// Usage:
//   node cli.js [--upper] [--repeat N] <text>
//
// Flags may appear in any order before the positional <text>.
//   --upper      uppercase the text
//   --repeat N   print the resolved line N times (one per line); default 1
//
// A missing, blank, or non-integer repeat count is a usage error.

function usage() {
  console.error("usage: cli.js [--upper] [--repeat N] <text>");
  process.exit(1);
}

const args = process.argv.slice(2);

let upper = false;
let repeat = 1;
let text = null;

for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (a === "--upper") {
    upper = true;
  } else if (a === "--repeat") {
    const raw = args[i + 1];
    // "Empty-string case": a blank repeat count is a usage error, never a guess.
    if (raw === undefined || raw === "") usage();
    const n = Number(raw);
    if (!Number.isInteger(n) || n < 0) usage();
    repeat = n;
    i += 1;
  } else if (a.startsWith("--")) {
    usage();
  } else {
    text = a;
  }
}

if (text === null) usage();

const line = upper ? text.toUpperCase() : text;
for (let r = 0; r < repeat; r++) console.log(line);

