// shout CLI test suite (node:test, no external deps).
// Spawns the real CLI and asserts stdout / stderr / exit codes.
"use strict";

const { test } = require("node:test");
const assert = require("node:assert");
const { execFileSync, spawnSync } = require("node:child_process");
const path = require("node:path");

const CLI = path.join(__dirname, "..", "cli.js");

function run(args) {
  return spawnSync(process.execPath, [CLI, ...args], { encoding: "utf8" });
}

test("--upper --repeat 3 hi prints HI on three lines", () => {
  const r = run(["--upper", "--repeat", "3", "hi"]);
  assert.strictEqual(r.status, 0);
  const lines = r.stdout.split("\n").filter((l) => l !== "");
  assert.strictEqual(lines.length, 3);
  assert.ok(lines.every((l) => l === "HI"));
});

test("--repeat 2 hi prints hi on two lines", () => {
  const r = run(["--repeat", "2", "hi"]);
  assert.strictEqual(r.status, 0);
  const lines = r.stdout.split("\n").filter((l) => l !== "");
  assert.strictEqual(lines.length, 2);
  assert.ok(lines.every((l) => l === "hi"));
});

test("flag order is independent", () => {
  const a = run(["--repeat", "2", "--upper", "hi"]);
  const b = run(["--upper", "--repeat", "2", "hi"]);
  assert.strictEqual(a.status, 0);
  assert.strictEqual(a.stdout, b.stdout);
});

test("omitted --repeat behaves as --repeat 1", () => {
  const r = run(["--upper", "hi"]);
  assert.strictEqual(r.status, 0);
  assert.strictEqual(r.stdout.trim(), "HI");
});

test("blank --repeat value is a usage error (non-zero exit)", () => {
  const r = run(["--repeat", "", "hi"]);
  assert.notStrictEqual(r.status, 0);
  assert.match(r.stderr, /usage:/);
  assert.strictEqual(r.stdout, "");
});

test("non-integer repeat count is a usage error", () => {
  const r = run(["--repeat", "abc", "hi"]);
  assert.notStrictEqual(r.status, 0);
  assert.match(r.stderr, /usage:/);
});

test("negative repeat count is a usage error", () => {
  const r = run(["--repeat", "-1", "hi"]);
  assert.notStrictEqual(r.status, 0);
  assert.match(r.stderr, /usage:/);
});

test("missing argument prints usage", () => {
  const r = run([]);
  assert.notStrictEqual(r.status, 0);
  assert.match(r.stderr, /usage:/);
});

